// Journal fictif de l'intervention : il servira de chronologie au REX.
// L'adresse IP et le mot de passe sont là exprès : WF2 doit les masquer avant Claude.
const key = $('Créer l\'incident P1').first().json.key;
const lignes = [
  '09:02 - Alerte supervision : ERP-PROD ne répond plus (HTTP 503 sur le portail). Incident P1 ouvert.',
  '09:10 - Diagnostic : pool de connexions à la base 10.20.4.15 saturé (500/500).',
  '09:25 - Redémarrage du service applicatif, reconnexion avec le compte de service password=Erp2026! (à changer).',
  '09:41 - Service rétabli, temps de réponse normaux. Cause probable : batch de clôture lancé en journée.',
  '09:50 - Résolu. Action proposée : planifier le batch de clôture la nuit et alerter à 80 % du pool.',
];
return lignes.map((texte) => ({ json: { key, texte } }));

// Cherche la transition qui mène à un statut « terminé » (catégorie done),
// en écartant l'annulation : un incident annulé n'a pas de REX.
const key = $('Créer l\'incident P1').first().json.key;
const liste = $input.first().json.transitions || [];
const finales = liste.filter((t) => t.to?.statusCategory?.key === 'done' && !/annul|cancel/i.test(t.to.name + ' ' + t.name));
const t = finales.find((x) => /termin|done|r[ée]sol/i.test(x.to.name)) || finales[0];
if (!t) throw new Error('Aucune transition vers un statut terminé (hors annulation). Disponibles : ' + liste.map((x) => `${x.name} → ${x.to?.name}`).join(', '));
return [{ json: { key, transitionId: t.id, transition: t.name, statut: t.to.name } }];
